sys_script_client.script:
function onLoad() {

    // =====================================================
    // ROLE CHECK
    // =====================================================

    var isInterviewer = g_user.hasRole('x_snc_college_pl_0.interviewer');
    var isPlacementOfficer = g_user.hasRole('x_snc_college_pl_0.placement_officer');
    var isStudent = g_user.hasRole('x_snc_college_pl_0.student_user');

    // Student = ALWAYS READ ONLY
    if (isStudent && !isInterviewer && !isPlacementOfficer) {

        var studentFields = g_form.getEditableFields();

        for (var i = 0; i < studentFields.length; i++) {
            g_form.setReadOnly(studentFields[i], true);
        }

        return;
    }

    // Only HR/Interviewer and Placement Officer
    // should continue with editing logic.
    if (!isInterviewer && !isPlacementOfficer) {
        return;
    }


    // =====================================================
    // NEW RECORD
    // =====================================================

    if (g_form.isNewRecord()) {

        g_form.setReadOnly('result', true);
        g_form.setReadOnly('feedback', true);

        return;
    }


    // =====================================================
    // EXISTING RECORD
    // =====================================================

    var status = g_form.getValue('status');
    var result = g_form.getValue('result');
    var feedback = g_form.getValue('feedback');


    // =====================================================
    // COMPLETED + RESULT + FEEDBACK ALREADY SAVED
    // → LOCK EVERYTHING
    // =====================================================

    if (status == 'completed' &&
        result != '' &&
        feedback != '') {

        var fields = g_form.getEditableFields();

        for (var j = 0; j < fields.length; j++) {
            g_form.setReadOnly(fields[j], true);
        }

        return;
    }


    // =====================================================
    // COMPLETED BUT RESULT / FEEDBACK EMPTY
    // → ALLOW HR / PLACEMENT OFFICER TO COMPLETE
    // =====================================================

    if (status == 'completed') {

        g_form.setReadOnly('result', false);
        g_form.setReadOnly('feedback', false);

        return;
    }


    // =====================================================
    // SCHEDULE / IN PROGRESS
    // → RESULT + FEEDBACK READ ONLY
    // =====================================================

    g_form.setReadOnly('result', true);
    g_form.setReadOnly('feedback', true);
}
